"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[51233],{28453:(e,t,o)=>{o.d(t,{R:()=>s,x:()=>l});var a=o(96540);const n={},r=a.createContext(n);function s(e){const t=a.useContext(r);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),a.createElement(r.Provider,{value:t},e.children)}},55393:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>i,contentTitle:()=>l,default:()=>d,frontMatter:()=>s,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"qiangguo/applaudforshfl2","title":"","description":"Today Shang Fulin finally spoke. Now that\'s a real man. Good on you, Shandong man. \\"The split share structure reform is an arrow that has left the bow\u2014there is no turning back.\\" It\'s decided. Absolutely do not pay any attention to the clamoring of those with ulterior motives. After a 13-year bull market, going through a 7-8 year adjustment is only natural. Where in the world is there a stock market that only goes up and never comes down? Back then, Taiwan\'s market crashed from over 10,000 and lost more than half, Japan\'s fell from over 40,000 to below 10,000\u2014the current adjustment of China\'s stock market is child\'s play. To surrender to trapped bulls over this would be far too humiliating\u2014how could anyone do such a thing?","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/applaudforshfl2.md","sourceDirName":"qiangguo","slug":"/qiangguo/applaudforshfl2","permalink":"/en/qiangguo/applaudforshfl2","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"applaudforshfl2","title":"","hide_table_of_contents":true,"sidebar_label":"Applauding Shang Fulin \u2014 Those Attempting to Blackmail the Government Using the Share Structure Reform Issue Must Be Legally Sanctioned (2005-5-16)"},"sidebar":"qiangguoSidebar","previous":{"title":"Applauding Shang Fulin \u2014 A Regulator Who Can\'t Provoke Interest Warfare Among All Parties Is Not a Good Regulator (2005-6-20)","permalink":"/en/qiangguo/applaudforshfl"},"next":{"title":"\u4e00\u5982\u88ab\u6587\u9769\u5957\u7262\u7684\u4e00\u7fa4\uff0c\u67d0\u4e9b\u4eba\u4f01\u56fe\u5229\u7528\u80a1\u5e02\u5236\u9020\u8206\u8bba\u8981\u631f\u653f\u5e9c\uff0c\u7a76\u7adf\u610f\u6b32\u4f55\u4e3a\uff1f","permalink":"/en/qiangguo/publicopinion"}}');var n=o(74848),r=o(28453);const s={id:"applaudforshfl2",title:"",hide_table_of_contents:!0,sidebar_label:"Applauding Shang Fulin \u2014 Those Attempting to Blackmail the Government Using the Share Structure Reform Issue Must Be Legally Sanctioned (2005-5-16)"},l="Applause for Shang Fulin \u2014 Those Who Attempt to Hold the Government Hostage Over the Split Share Structure Issue Must Be Dealt With by Law (2005-5-16)",i={},h=[];function u(e){const t={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"applause-for-shang-fulin--those-who-attempt-to-hold-the-government-hostage-over-the-split-share-structure-issue-must-be-dealt-with-by-law-2005-5-16",children:"Applause for Shang Fulin \u2014 Those Who Attempt to Hold the Government Hostage Over the Split Share Structure Issue Must Be Dealt With by Law (2005-5-16)"})}),"\n",(0,n.jsx)(t.p,{children:"Today Shang Fulin finally spoke. Now that's a real man. Good on you, Shandong man. \"The split share structure reform is an arrow that has left the bow\u2014there is no turning back.\" It's decided. Absolutely do not pay any attention to the clamoring of those with ulterior motives. After a 13-year bull market, going through a 7-8 year adjustment is only natural. Where in the world is there a stock market that only goes up and never comes down? Back then, Taiwan's market crashed from over 10,000 and lost more than half, Japan's fell from over 40,000 to below 10,000\u2014the current adjustment of China's stock market is child's play. To surrender to trapped bulls over this would be far too humiliating\u2014how could anyone do such a thing?"}),"\n",(0,n.jsx)(t.p,{children:"Until the bulls die, the bear market won't end. The market won't cater to you just because you don't like it\u2014who do you think you are? You can condemn the wickedness of interest groups in the split share structure resolution, but when you entered the stock market, wasn't the split share structure already a reality? Did it suddenly appear out of nowhere? Didn't anyone tell you this split share structure would eventually be resolved? And wouldn't the resolution carry market risk? Didn't you know that risk is borne by yourself? Problems are meant to be solved. You want to halt it? No way!"}),"\n",(0,n.jsx)(t.p,{children:"The market is a place for intellectual games. If you don't have the brains, don't come in. Can't you put money in a bank? Didn't you enter the stock market out of greed? When you lose, you blame the government\u2014but when you win, would you donate the money to the government? The market has no sympathy for the weak. Anyone begging for protection should not be in the market. If you don't even have this basic quality, what are you doing in the stock market?"}),"\n",(0,n.jsx)(t.p,{children:"Those who, because they're trapped, attempt to use the split share structure issue to hold the government hostage are harboring sinister intentions, and they must be dealt with by law. Even from a market perspective, if the bulls are satisfied, the bears still aren't\u2014what about them? You're losing money, but plenty of others are making money. If the bulls don't die, what are the bears supposed to do? Don't use talk of market collapse to threaten the government. Over a decade ago, the market plunged from 1,558 to 333 and there was no collapse. Even if it did collapse, didn't it eventually hit new highs again? The world's stock markets are full of such examples."}),"\n",(0,n.jsx)(t.p,{children:"Strike when the time is right\u2014that's from a song about your Shandong people. Applause for Shang Fulin. Hold firm like a Shandong man, and victory is not far away."})]})}function d(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(u,{...e})}):u(e)}}}]);